import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class BookSearchIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void matches_title_substring_ignoring_case_and_returns_id_title_status() throws Exception {
        registerBook("검색Spring in Action");
        registerBook("SPRING 입문");
        registerBook("검색 테스트 Kotlin");

        mockMvc.perform(get("/books").param("title", "spring"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[0].title").value("SPRING 입문"))
                .andExpect(jsonPath("$[0].status").value("AVAILABLE"))
                .andExpect(jsonPath("$[0].id").isNotEmpty())
                .andExpect(jsonPath("$[1].title").value("검색Spring in Action"));
    }

    @Test
    void returns_empty_array_when_no_title_matches() throws Exception {
        mockMvc.perform(get("/books").param("title", "존재하지않는제목-zz9"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));
    }

    @Test
    void treats_like_wildcards_in_keyword_as_plain_characters() throws Exception {
        registerBook("할인 100% 도서");
        registerBook("할인 1000 도서");

        mockMvc.perform(get("/books").param("title", "100%"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].title").value("할인 100% 도서"));
    }

    @Test
    void blank_title_returns_400() throws Exception {
        mockMvc.perform(get("/books").param("title", "  "))
                .andExpect(status().isBadRequest());
    }

    private String registerBook(String title) throws Exception {
        String response = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(Map.of("title", title))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode json = objectMapper.readTree(response);
        return json.get("id").asText();
    }
}
